def _field(role, name, role_operators):
    for operator in role_operators.get(role, ()):
        source = _HDA_FIELDS.get(operator)
        if source is None:
            continue
        for template, record in source['parameters'].items():
            if (template == name or '#' in template and
                    re.fullmatch(re.escape(template).replace(r'\#', r'\d+'), name)):
                if 'invisible' in record.get('flags', ()):
                    return None
                return {'operator': operator, 'parameter': template,
                        'type': record['type'], 'size': record['size'],
                        'section_sha256': source['section_sha256'],
                        'archive_sha256': source['archive_sha256']}
    return None


def guard_controls(pack, version, controls, branch=None):
    if version not in PREPARATION_VERSIONS:
        return controls
    key = pack + ('/' + branch if branch else '')
    role_operators = _ROLE_OPERATORS.get(key, {})
    for control in controls.values():
        if 'product_definition' in control:
            from .product_control_definitions import PREPARATION_CAPTURE_REQUIREMENTS
            control['product_definition']['preparation_capture_requirements'] = {
                **PREPARATION_CAPTURE_REQUIREMENTS, 'versions': [version]}
        required = [(control['role'], name) for name in control.get('aliases', ())]
        required += [(item[0], item[1]) for item in control.get('required_gates', ())]
        required += list(control.get('targets', ()))
        observed, missing = [], []
        for role, name in required:
            fact = _field(role, name, role_operators)
            if fact is None:
                missing.append({'role': role, 'parameter': name,
                                'operators': list(role_operators.get(role, ()))})
            else:
                observed.append(fact)
        control['native_basis'] = {'version': version, 'source': BASIS_PATH,
            'scope': 'STATIC_HDA_PARAMETER_FIELDS_ONLY', 'native_execution': False,
            'observed': observed, 'missing': missing}
        if required and missing:
            control.update(native_status='blocked', blocker='H22_459_NATIVE_TEMPLATE_REQUIRED')
        elif control.get('native_status', 'mapped') == 'mapped':
            if not required or missing:
                control.update(native_status='blocked', blocker='H22_459_NATIVE_TEMPLATE_REQUIRED')
            else:
                control['native_status'] = 'mapped'
    return controls


def versioned_controls(function):
    @wraps(function)
    def checked(*args, **kwargs):
        controls = function(*args, **kwargs)
        pack = args[0] if args else kwargs.get('pack', kwargs.get('pack_id'))
        version = args[1] if len(args) > 1 else kwargs['version']
        branch = args[2] if len(args) > 2 else kwargs.get('branch')
        return guard_controls(pack, version, controls, branch)
    return checked
